// Contromossa quiz - pin probe / self-test
// Generated by firmware/tools/build.mjs - edit firmware/src instead.

// ===== probe_main.ts =====
// =============================================================================
//  PIN PROBE / SELF-TEST  (standalone firmware, not part of the game)
//
//  Use it on the real edu:bit with the real M5 Unit Key plugged into each
//  connector, to find out which micro:bit pin each connector uses, whether the
//  switch bounces, and whether the speaker works.  See docs/HARDWARE.md.
//
//   Button A : next mode        Button B : play a test tone
//   Mode 1 (pins)   : press a key -> the pin number scrolls on the LEDs and is
//                     written to USB serial ("LOW P12").
//   Mode 2 (bounce) : press a key -> shows how many times the line toggled in
//                     the first 30 ms (and prints the timings on serial).
//  At boot the idle level of every candidate pin is printed on serial; a pin
//  that is already LOW with nothing pressed is not usable as a key.
// =============================================================================

const PROBE_PINS: number[] = [DigitalPin.P0, DigitalPin.P1, DigitalPin.P2, DigitalPin.P8, DigitalPin.P12,
    DigitalPin.P13, DigitalPin.P14, DigitalPin.P15, DigitalPin.P16];
const PROBE_NAMES: number[] = [0, 1, 2, 8, 12, 13, 14, 15, 16];

let probeMode = 1;

for (let i = 0; i < PROBE_PINS.length; i++) pins.setPull(PROBE_PINS[i], PinPullMode.PullUp);

serial.redirectToUSB();
basic.pause(200);
let probeBoot = "BOOT idle levels:";
for (let i = 0; i < PROBE_PINS.length; i++) probeBoot += " P" + PROBE_NAMES[i] + "=" + pins.digitalReadPin(PROBE_PINS[i]);
serial.writeString(probeBoot + "\n");
basic.showString("1");

input.onButtonPressed(Button.A, function () {
    probeMode = probeMode == 1 ? 2 : 1;
    basic.showString("" + probeMode);
    serial.writeString("MODE " + probeMode + "\n");
});

input.onButtonPressed(Button.B, function () {
    serial.writeString("TONE\n");
    music.playTone(440, 300);
    music.playTone(880, 300);
});

function probeFirstLow(): number {
    for (let i = 0; i < PROBE_PINS.length; i++) {
        if (pins.digitalReadPin(PROBE_PINS[i]) == 0) return i;
    }
    return -1;
}

control.inBackground(function () {
    while (true) {
        const i = probeFirstLow();
        if (i >= 0) {
            const pin = PROBE_PINS[i];
            if (probeMode == 1) {
                // confirm it is stable for 20 ms, then report once per press
                basic.pause(20);
                if (pins.digitalReadPin(pin) == 0) {
                    serial.writeString("LOW P" + PROBE_NAMES[i] + "\n");
                    basic.showString("P" + PROBE_NAMES[i]);
                    while (pins.digitalReadPin(pin) == 0) basic.pause(10);
                    serial.writeString("HIGH P" + PROBE_NAMES[i] + "\n");
                }
            } else {
                // bounce measurement: count transitions for 30 ms after the first falling edge
                const t0 = input.runningTimeMicros();
                let last = 0;
                let edges = 0;
                let log = "";
                while (input.runningTimeMicros() - t0 < 30000) {
                    const v = pins.digitalReadPin(pin);
                    if (v != last) {
                        edges++;
                        last = v;
                        log += " " + (input.runningTimeMicros() - t0) + "us:" + v;
                    }
                }
                serial.writeString("BOUNCE P" + PROBE_NAMES[i] + " edges=" + edges + log + "\n");
                basic.showNumber(edges);
                while (pins.digitalReadPin(pin) == 0) basic.pause(10);
            }
        }
        basic.pause(5);
    }
});
